import { useState } from 'react';
import { X, Trash2, Loader2, CheckCircle } from 'lucide-react';
import { useCart } from '../../context/CartContext';
import api from '../../lib/axios';

export const CartDrawer = () => {
  const { cart, isCartOpen, setIsCartOpen, removeFromCart, updateQuantity, clearCart } = useCart();
  const [deliveryLocation, setDeliveryLocation] = useState('');
  const [paymentMethod, setPaymentMethod] = useState('Cash on Delivery');
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  if (!isCartOpen) return null;

  const totalCartValue = cart.reduce((sum, item) => sum + (item.pricePerKg * item.orderQuantity), 0);

  const handleCheckout = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      // Loop through cart items and post each order to the database
      const orderPromises = cart.map(item => 
        api.post('/orders', {
          produceId: item._id,
          quantityKg: item.orderQuantity,
          deliveryLocation,
          paymentMethod
        })
      );
      
      await Promise.all(orderPromises);
      setIsSuccess(true);
      setTimeout(() => {
        clearCart();
        setIsCartOpen(false);
        setIsSuccess(false);
      }, 2500);
    } catch (err) {
      alert('Failed to process some orders. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-black/40 backdrop-blur-sm">
      <div className="w-full max-w-md bg-white h-full shadow-2xl flex flex-col animate-slide-in-right">
        
        {/* Header */}
        <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between bg-gray-50">
          <h3 className="text-xl font-bold text-gray-900">Your Cart</h3>
          <button onClick={() => setIsCartOpen(false)} className="p-2 bg-gray-200 rounded-full hover:bg-gray-300">
            <X size={20} />
          </button>
        </div>

        {isSuccess ? (
          <div className="flex-1 flex flex-col items-center justify-center p-8 text-center">
            <CheckCircle className="text-farmGreen mb-4" size={64} />
            <h3 className="text-2xl font-bold text-gray-900 mb-2">Orders Placed!</h3>
            <p className="text-gray-500">Track your orders from the sidebar menu.</p>
          </div>
        ) : cart.length === 0 ? (
          <div className="flex-1 flex flex-col items-center justify-center p-8 text-center text-gray-400">
            <p className="font-medium text-lg">Your cart is empty.</p>
          </div>
        ) : (
          <>
            {/* Cart Items List */}
            <div className="flex-1 overflow-y-auto p-6 space-y-4 border-b border-gray-100">
              {cart.map((item) => (
                <div key={item._id} className="flex gap-4 items-center bg-gray-50 p-3 rounded-xl border border-gray-200">
                  <div className="flex-1">
                    <h4 className="font-bold text-gray-900">{item.cropType}</h4>
                    <p className="text-xs text-gray-500">GHS {item.pricePerKg.toFixed(2)} / kg</p>
                    <div className="mt-2 flex items-center gap-2">
                      <input 
                        type="number" min="1" max={item.weightKg} value={item.orderQuantity}
                        onChange={(e) => updateQuantity(item._id, e.target.value)}
                        className="w-16 px-2 py-1 border rounded text-sm outline-none focus:border-farmGreen"
                      />
                      <span className="text-xs font-medium text-gray-500">kg</span>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="font-bold text-gray-900 mb-2">GHS {(item.pricePerKg * item.orderQuantity).toFixed(2)}</p>
                    <button onClick={() => removeFromCart(item._id)} className="text-red-500 p-1 hover:bg-red-50 rounded">
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              ))}
            </div>

            {/* Checkout Form */}
            <form onSubmit={handleCheckout} className="p-6 bg-gray-50">
              <div className="space-y-4 mb-6">
                <input
                  type="text" required placeholder="Delivery Location (e.g. Accra Central)"
                  value={deliveryLocation} onChange={(e) => setDeliveryLocation(e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg outline-none focus:border-farmGreen"
                />
                <select
                  value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg outline-none bg-white focus:border-farmGreen"
                >
                  <option value="Cash on Delivery">Cash on Delivery</option>
                  <option value="Manual Mobile Money">Manual Mobile Money</option>
                </select>
              </div>

              <div className="flex items-center justify-between mb-4">
                <span className="font-bold text-gray-700">Total Order</span>
                <span className="text-2xl font-extrabold text-farmGreen">GHS {totalCartValue.toFixed(2)}</span>
              </div>
              <button 
                type="submit" disabled={isLoading}
                className="w-full py-3.5 bg-farmGreen hover:bg-farmGreen-dark text-white font-bold rounded-xl flex justify-center items-center"
              >
                {isLoading ? <Loader2 className="animate-spin" /> : 'Confirm Checkout'}
              </button>
            </form>
          </>
        )}
      </div>
    </div>
  );
};
